import type { Diagnostic } from "../contract/v5";
import type { StaleHandleError } from "../contract/handle";
import { StaleMotionHandleError } from "../contract/motion-handle";
import { StaleTrackHandleError } from "../contract/track-handle";
import { unreachable } from "../domain/exhaustive";

/**
 * Every refusal the project runtime throws, as data, and the one describer that renders each of them.
 *
 * `schema-refusals.ts` proved there was a union here already: eight functions, each throwing a
 * `TypeError` whose message opens with a rule id, so the kind of a refusal was a real fact encoded
 * as a prefix inside human prose. A caller that wanted to branch on one had to parse a string, and
 * the rule id, then detail, then remedy template was retyped once per function.
 *
 * So the payload becomes a closed union and the message becomes a rendering of it. Three things are
 * deliberately unchanged. Refusals still throw, because returning them would be an API break and
 * would let a caller ignore one. Every message is byte-identical to what it was, which is what makes
 * this slice provably behaviour-preserving: every message-anchored test stays green, and any message
 * change is owed its own deliberate commit. And each refusal keeps the error class it already threw,
 * which is why `refusalError` is a second switch beside `describeRefusal` rather than one
 * constructor: a stale handle is the `StaleHandleError` family the contract layer owns, a disposed
 * project is a plain `Error`, and the rest are the `TypeError` family. Neither class here assigns
 * `name`, because the classes they replace do not.
 *
 * Issue #443, phase A step 1.
 */
declare const REFUSAL_BRAND: unique symbol;

/**
 * The mint mark that keeps the union below closed as well as discriminated.
 *
 * The device `graph-runtime-state.ts` already uses, for the reason issue #387 gave: a variant
 * declaring only its discriminant is not closed, because TypeScript's excess-property check reads a
 * fresh object literal rather than a value arriving through a variable. Declared, never exported and
 * never assigned at runtime, so no other module can name the key and no property exists to carry.
 */
interface RefusalBrand {
  readonly [REFUSAL_BRAND]: true;
}

type Minted<Shape extends { readonly kind: string }> = Shape & RefusalBrand;

/** What a stale handle was captured against, named by the kind of handle that refused. */
export interface HandleTarget {
  readonly kind: "track" | "motion";
  readonly id: string;
}

interface DisposedShape {
  readonly kind: "disposed";
}

interface NestedRecipeShape {
  readonly kind: "nested-recipe";
}

interface ImmediateInRecipeShape {
  readonly kind: "immediate-in-recipe";
  readonly verb: string;
}

interface ImmediateInBatchShape {
  readonly kind: "immediate-in-batch";
  readonly verb: string;
}

interface CommitInFlightShape {
  readonly kind: "commit-in-flight";
}

interface StructuralInBatchShape {
  readonly kind: "structural-in-batch";
}

interface UnknownMotionShape {
  readonly kind: "unknown-motion";
  readonly motionId: string;
}

interface UnknownNodeShape {
  readonly kind: "unknown-node";
  readonly nodeId: string;
}

interface StaleHandleShape {
  readonly kind: "stale-handle";
  readonly target: HandleTarget;
}

interface UnboundGroupShape {
  readonly kind: "unbound-group";
  readonly nodeId: string;
  readonly plugin: string;
}

interface ReservedGoalSlotShape {
  readonly kind: "reserved-goal-slot";
  readonly plugin: string;
  readonly slot: string;
}

interface PropertyEntryShape {
  readonly kind: "property-entry";
  readonly nodeId: string;
  readonly plugin: string;
}

interface InvalidDefinitionShape {
  readonly kind: "invalid-definition";
  readonly diagnostics: readonly Diagnostic[];
}

/** What a caller hands `refuse`: one refusal, before it is minted. */
export type RefusalShape =
  | DisposedShape
  | NestedRecipeShape
  | ImmediateInRecipeShape
  | ImmediateInBatchShape
  | CommitInFlightShape
  | StructuralInBatchShape
  | UnknownMotionShape
  | UnknownNodeShape
  | StaleHandleShape
  | UnboundGroupShape
  | ReservedGoalSlotShape
  | PropertyEntryShape
  | InvalidDefinitionShape;

/**
 * One refusal, minted, and the whole set of them.
 *
 * Distributed by hand rather than written as one intersection over the shape union, so every variant
 * carries the mark itself and discriminant narrowing reads a plain union at every arm below.
 */
export type Refusal =
  | Minted<DisposedShape>
  | Minted<NestedRecipeShape>
  | Minted<ImmediateInRecipeShape>
  | Minted<ImmediateInBatchShape>
  | Minted<CommitInFlightShape>
  | Minted<StructuralInBatchShape>
  | Minted<UnknownMotionShape>
  | Minted<UnknownNodeShape>
  | Minted<StaleHandleShape>
  | Minted<UnboundGroupShape>
  | Minted<ReservedGoalSlotShape>
  | Minted<PropertyEntryShape>
  | Minted<InvalidDefinitionShape>;

/** Mints one refusal, and is the only expression in the program that produces a `Refusal`. */
function mintRefusal(shape: RefusalShape): Refusal {
  return Object.freeze(shape) as unknown as Refusal;
}

/**
 * Renders a diagnostic list as one line, and is the one owner of that rendering.
 *
 * Moved here from `schema-refusals.ts` because `invalid-definition` renders through it, and
 * re-exported from there so no call site and no test moves. The output is byte-identical.
 */
export function describeDiagnostics(diagnostics: readonly Diagnostic[]): string {
  return diagnostics
    .map(({ ruleId, path, message }) => `${ruleId} at ${path}: ${message}`)
    .join(" ");
}

/**
 * Answers the error a stale handle refuses with, which the contract layer owns.
 *
 * The sentence is not respelled here. `StaleHandleError` owns it, each subclass passes the noun, and
 * this switch only decides which of the two a target names. That is why `describeRefusal` reads the
 * message off this error rather than templating a second copy of it.
 */
export function staleHandleError(target: HandleTarget): StaleHandleError {
  switch (target.kind) {
    case "track":
      return new StaleTrackHandleError(target.id);
    case "motion":
      return new StaleMotionHandleError(target.id);
    default:
      return unreachable(target.kind);
  }
}

/**
 * The message one refusal renders to, and the acceptance test for this whole slice.
 *
 * Every arm reproduces what the function it replaces produced, byte for byte. A variant added later
 * fails `typecheck` here rather than falling into whichever arm was written last.
 */
export function describeRefusal(refusal: Refusal): string {
  switch (refusal.kind) {
    case "disposed":
      return "ProjectRuntime is disposed.";
    case "nested-recipe":
      return "schema-transaction-nested: A recipe is already open. Finish it before opening another.";
    case "immediate-in-recipe":
      return `schema-transaction-immediate: "${refusal.verb}" applies immediately and cannot travel with a recipe. Call it outside edit().`;
    case "immediate-in-batch":
      return `value-batch-immediate: "${refusal.verb}" publishes or mounts and cannot travel with a value batch. Call it outside values().`;
    case "commit-in-flight":
      return "schema-commit-reentrant: A structural commit is already in flight. Ask for it once this one has returned.";
    case "structural-in-batch":
      return "value-batch-structural: A value batch is open. Ask for it once values() has returned.";
    case "unknown-motion":
      return `Unknown motion "${refusal.motionId}".`;
    case "unknown-node":
      return `Unknown graph node "${refusal.nodeId}".`;
    case "stale-handle":
      return staleHandleError(refusal.target).message;
    case "unbound-group":
      return `keyframe-group-unbound: "${refusal.nodeId}" authors no "${refusal.plugin}" group. Use setKeyframeGroup to originate one.`;
    case "reserved-goal-slot":
      return `keyframe-goal-slot-reserved: Slot "${refusal.slot}" of "${refusal.plugin}" holds a solver's goals. Use setGoal to bind one entry of it, or removeGoal to drop one.`;
    case "property-entry":
      return `keyframe-entry-shape: "${refusal.nodeId}" authors "${refusal.plugin}" as a property, not a group. Use replace() to change an entry's shape.`;
    case "invalid-definition":
      return describeDiagnostics(refusal.diagnostics);
    default:
      return unreachable(refusal);
  }
}

/**
 * The `TypeError` family every named schema refusal throws, now carrying its payload.
 *
 * `TypeError` rather than `Error` because that is what each of these threw, so existing
 * `catch (error) { if (error instanceof TypeError) }` code keeps matching. `name` is left alone for
 * the same reason: today's value is `"TypeError"`, and a rename would be an observable change in a
 * slice whose whole claim is that nothing observable moved.
 */
export class RefusalError extends TypeError {
  readonly refusal: Refusal;
  constructor(refusal: Refusal) {
    super(describeRefusal(refusal));
    this.refusal = refusal;
  }
}

/**
 * The one refusal that is not a `TypeError`, because `#assertLive` threw a plain `Error`.
 *
 * A separate class rather than a widening of the family above, so the payload becomes inspectable
 * without the disposed refusal changing what it is. See `RefusalError` on why `name` is untouched.
 */
export class DisposedProjectError extends Error {
  readonly refusal: Refusal;
  constructor(refusal: Refusal) {
    super(describeRefusal(refusal));
    this.refusal = refusal;
  }
}

/** The error one refusal is thrown as. Total, so a new variant owes a decision here too. */
export function refusalError(refusal: Refusal): Error {
  switch (refusal.kind) {
    case "stale-handle":
      return staleHandleError(refusal.target);
    case "disposed":
      return new DisposedProjectError(refusal);
    case "nested-recipe":
    case "immediate-in-recipe":
    case "immediate-in-batch":
    case "commit-in-flight":
    case "structural-in-batch":
    case "unknown-motion":
    case "unknown-node":
    case "unbound-group":
    case "reserved-goal-slot":
    case "property-entry":
    case "invalid-definition":
      return new RefusalError(refusal);
    default:
      return unreachable(refusal);
  }
}

/** Refuses, and is the only expression that throws one of these. Mints on the way through. */
export function refuse(shape: RefusalShape): never {
  throw refusalError(mintRefusal(shape));
}

import type { Diagnostic } from "../contract/v5";
import type { LiveWriteResult } from "../domain/track";
import { unreachable } from "../domain/exhaustive";
import { refuse, type HandleTarget } from "./refusal";

/**
 * The three boolean-plus-optional pairs the project runtime decodes by hand, as closed unions.
 *
 * Each of them is a type that cannot state the implication its callers rely on, so each caller
 * restates it. `{ valid, value? }` cannot say that valid implies a value, so `project-runtime.ts`
 * writes `!validation.valid || !validation.value` five times, and that second clause is dead weight
 * that exists only to satisfy the compiler. `LiveWriteResult | undefined` is three outcomes wearing
 * an optional over a boolean, decoded by the same three-line dance in two places. And handle
 * liveness is ten private methods that differ in whether they throw, whether they assert liveness,
 * and whether they answer an entry or an id.
 *
 * One deliberate departure from the shape issue #443 sketches. Its `LiveWrite` gives `patched` no
 * payload, but `#recompileKeyframes` reads `written?.progress` on both outcomes, so a `patched`
 * carrying nothing would drop a progress the runtime seeks to today. The hook always answers a
 * progress; only whether a rebuild is owed differs, so that is the only thing the discriminant says.
 *
 * Issue #443, phase A step 2.
 */
declare const RESULT_BRAND: unique symbol;

/**
 * The mint mark shared by the three unions in this module, for the reason issue #387 gave.
 *
 * One mark rather than three, because these are minted in one place and none of them is assignable
 * to another: their discriminants are disjoint, so the mark has only closedness left to buy.
 */
interface ResultBrand {
  readonly [RESULT_BRAND]: true;
}

type Minted<Shape extends { readonly kind: string }> = Shape & ResultBrand;

function mint<Shape extends { readonly kind: string }>(shape: Shape): Minted<Shape> {
  return Object.freeze(shape) as unknown as Minted<Shape>;
}

interface AcceptedShape<T> {
  readonly kind: "accepted";
  readonly value: T;
  readonly diagnostics: readonly Diagnostic[];
}

interface RejectedShape {
  readonly kind: "rejected";
  readonly diagnostics: readonly Diagnostic[];
}

/** A validated candidate: accepted with its value, or rejected with why. No non-null assertion. */
export type Validated<T> = Minted<AcceptedShape<T>> | Minted<RejectedShape>;

/**
 * Reads one validation result as a union, and is the only place the two-field encoding is decoded.
 *
 * Structural in its parameter rather than naming `TrackValidationResult`, because the same encoding
 * is answered for more than one candidate shape and this module owns none of them.
 */
export function validated<T>(result: {
  readonly valid: boolean;
  readonly value: T | null;
  readonly diagnostics: readonly Diagnostic[];
}): Validated<T> {
  const diagnostics = result.diagnostics;
  if (!result.valid || result.value === null) return mint<RejectedShape>({ kind: "rejected", diagnostics });
  return mint<AcceptedShape<T>>({ kind: "accepted", value: result.value, diagnostics });
}

/** The accepted value, or the refusal every one of those five sites throws today. */
export function expectValid<T>(result: Validated<T>): T {
  switch (result.kind) {
    case "accepted":
      return result.value;
    case "rejected":
      return refuse({ kind: "invalid-definition", diagnostics: result.diagnostics });
    default:
      return unreachable(result);
  }
}

interface NoHookShape {
  readonly kind: "no-hook";
}

interface PatchedShape {
  readonly kind: "patched";
  readonly progress: number;
}

interface NeedsRebuildShape {
  readonly kind: "needs-rebuild";
  readonly progress: number;
}

/** What the live-write seam answered: no hook at all, a patched timeline, or a rebuild owed. */
export type LiveWrite = Minted<NoHookShape> | Minted<PatchedShape> | Minted<NeedsRebuildShape>;

const NO_HOOK: LiveWrite = mint<NoHookShape>({ kind: "no-hook" });

/** Reads the seam's answer as a union. `undefined` was never a fourth outcome, only an absent one. */
export function liveWrite(result: LiveWriteResult | undefined): LiveWrite {
  if (result === undefined) return NO_HOOK;
  if (result.patched) return mint<PatchedShape>({ kind: "patched", progress: result.progress });
  return mint<NeedsRebuildShape>({ kind: "needs-rebuild", progress: result.progress });
}

interface LiveEntryShape<E> {
  readonly kind: "live";
  readonly entry: E;
}

interface StaleShape {
  readonly kind: "stale";
}

/** Whether a handle still points at what it was minted for, and what it points at when it does. */
export type Resolved<E> = Minted<LiveEntryShape<E>> | Minted<StaleShape>;

const STALE: Minted<StaleShape> = mint<StaleShape>({ kind: "stale" });

/** Answers a stale resolution, which carries nothing, so nothing has to be built to say so. */
export function stale<E>(): Resolved<E> {
  return STALE;
}

/**
 * Resolves one captured token against the entries a reader is looking at.
 *
 * The token comparison, once. Liveness of the runtime itself is a separate question and stays with
 * the phase that owns it, so a disposed runtime answers `stale()` at the one call site that asks.
 */
export function resolveToken<E extends { readonly token: number }>(
  entries: ReadonlyMap<string, E>,
  id: string,
  token: number,
): Resolved<E> {
  const entry = entries.get(id);
  if (entry === undefined || entry.token !== token) return STALE;
  return mint<LiveEntryShape<E>>({ kind: "live", entry });
}

/** Whether this resolution found what it was minted for. The `live` getter, as a discriminant read. */
export function isLive<E>(resolved: Resolved<E>): boolean {
  switch (resolved.kind) {
    case "live":
      return true;
    case "stale":
      return false;
    default:
      return unreachable(resolved);
  }
}

/** The resolved entry, or the stale-handle refusal the contract layer owns. */
export function expectLive<E>(resolved: Resolved<E>, target: HandleTarget): E {
  switch (resolved.kind) {
    case "live":
      return resolved.entry;
    case "stale":
      return refuse({ kind: "stale-handle", target });
    default:
      return unreachable(resolved);
  }
}

import { describe, expect, it } from "vitest";
import type { Diagnostic } from "../../../src/contract/v5";
import { StaleMotionHandleError } from "../../../src/contract/motion-handle";
import { StaleTrackHandleError } from "../../../src/contract/track-handle";
import {
  DisposedProjectError,
  RefusalError,
  describeDiagnostics,
  describeRefusal,
  refuse,
} from "../../../src/runtime/refusal";
import {
  expectLive,
  expectValid,
  isLive,
  liveWrite,
  resolveToken,
  stale,
  validated,
} from "../../../src/runtime/results";
import {
  commitInFlight,
  immediateInTransaction,
  nestedTransaction,
  propertyEntry,
  reservedGoalSlot,
  unboundGroup,
  valueBatchImmediate,
  valueBatchStructural,
} from "../../../src/runtime/schema-refusals";

const message = (body: () => never): string => {
  try {
    body();
  } catch (error) {
    return (error as Error).message;
  }
  throw new Error("Expected a refusal.");
};

const thrown = (body: () => never): unknown => {
  try {
    body();
  } catch (error) {
    return error;
  }
  throw new Error("Expected a refusal.");
};

const diagnostic: Diagnostic = {
  ruleId: "keyframes-shape",
  path: "addTrack(a).keyframes",
  message: "Not a record.",
  severity: "error",
};

describe("the named refusals still say exactly what they said", () => {
  it("renders every message byte-identically", () => {
    expect(message(() => nestedTransaction())).toBe(
      "schema-transaction-nested: A recipe is already open. Finish it before opening another.",
    );
    expect(message(() => immediateInTransaction("setTrigger"))).toBe(
      'schema-transaction-immediate: "setTrigger" applies immediately and cannot travel with a recipe. Call it outside edit().',
    );
    expect(message(() => commitInFlight())).toBe(
      "schema-commit-reentrant: A structural commit is already in flight. Ask for it once this one has returned.",
    );
    expect(message(() => valueBatchImmediate("mount"))).toBe(
      'value-batch-immediate: "mount" publishes or mounts and cannot travel with a value batch. Call it outside values().',
    );
    expect(message(() => valueBatchStructural())).toBe(
      "value-batch-structural: A value batch is open. Ask for it once values() has returned.",
    );
    expect(message(() => unboundGroup("free:a", "opacity"))).toBe(
      'keyframe-group-unbound: "free:a" authors no "opacity" group. Use setKeyframeGroup to originate one.',
    );
    expect(message(() => reservedGoalSlot("ik", "goals"))).toBe(
      'keyframe-goal-slot-reserved: Slot "goals" of "ik" holds a solver\'s goals. Use setGoal to bind one entry of it, or removeGoal to drop one.',
    );
    expect(message(() => propertyEntry("free:a", "opacity"))).toBe(
      'keyframe-entry-shape: "free:a" authors "opacity" as a property, not a group. Use replace() to change an entry\'s shape.',
    );
  });

  it("keeps the TypeError family every one of them threw", () => {
    expect(thrown(() => nestedTransaction())).toBeInstanceOf(TypeError);
    expect(thrown(() => commitInFlight())).toBeInstanceOf(RefusalError);
    expect((thrown(() => valueBatchStructural()) as RefusalError).refusal.kind).toBe(
      "structural-in-batch",
    );
  });
});

describe("the refusals the runtime spells inline", () => {
  it("renders the two unknown-id refusals and the invalid definition one", () => {
    expect(describeRefusal((thrown(() => refuse({ kind: "unknown-motion", motionId: "m" })) as RefusalError).refusal)).toBe(
      'Unknown motion "m".',
    );
    expect(message(() => refuse({ kind: "unknown-node", nodeId: "free:a" }))).toBe(
      'Unknown graph node "free:a".',
    );
    expect(message(() => refuse({ kind: "invalid-definition", diagnostics: [diagnostic] }))).toBe(
      describeDiagnostics([diagnostic]),
    );
  });

  it("leaves a disposed project a plain Error and a stale handle its own class", () => {
    const disposed = thrown(() => refuse({ kind: "disposed" }));
    expect(disposed).toBeInstanceOf(DisposedProjectError);
    expect(disposed).not.toBeInstanceOf(TypeError);
    expect((disposed as Error).message).toBe("ProjectRuntime is disposed.");
    const track = thrown(() => refuse({ kind: "stale-handle", target: { kind: "track", id: "free:a" } }));
    expect(track).toBeInstanceOf(StaleTrackHandleError);
    expect((track as Error).message).toBe('Track "free:a" is no longer live.');
    const motion = thrown(() => refuse({ kind: "stale-handle", target: { kind: "motion", id: "m" } }));
    expect(motion).toBeInstanceOf(StaleMotionHandleError);
    expect((motion as Error).message).toBe('Motion "m" is no longer live.');
  });
});

describe("the three decoded results", () => {
  it("states validity as one discriminant", () => {
    const accepted = validated({ valid: true, value: 7, diagnostics: [] });
    expect(accepted.kind).toBe("accepted");
    expect(expectValid(accepted)).toBe(7);
    expect(validated({ valid: true, value: null, diagnostics: [] }).kind).toBe("rejected");
    const rejected = validated<number>({ valid: false, value: null, diagnostics: [diagnostic] });
    expect(() => expectValid(rejected)).toThrow(describeDiagnostics([diagnostic]));
  });

  it("states the three live-write outcomes, and keeps the progress a patch answered", () => {
    expect(liveWrite(undefined).kind).toBe("no-hook");
    const patched = liveWrite({ patched: true, progress: 0.25 });
    expect(patched.kind).toBe("patched");
    expect(patched.kind === "patched" ? patched.progress : undefined).toBe(0.25);
    const rebuild = liveWrite({ patched: false, progress: 0.5 });
    expect(rebuild.kind).toBe("needs-rebuild");
    expect(rebuild.kind === "needs-rebuild" ? rebuild.progress : undefined).toBe(0.5);
  });

  it("resolves a token once, and refuses a stale one with the handle's own error", () => {
    const entries = new Map([["free:a", { token: 2 }]]);
    const live = resolveToken(entries, "free:a", 2);
    expect(isLive(live)).toBe(true);
    expect(expectLive(live, { kind: "track", id: "free:a" }).token).toBe(2);
    expect(isLive(resolveToken(entries, "free:a", 1))).toBe(false);
    expect(isLive(resolveToken(entries, "free:b", 2))).toBe(false);
    expect(isLive(stale())).toBe(false);
    expect(() => expectLive(stale(), { kind: "motion", id: "m" })).toThrow(StaleMotionHandleError);
  });
});

